parameters.jsCode:
const items = $input.all();
const queryOriginal = ($('Google Search Scrapper').first().json.body || {}).queries || "";
const resultadosLimpos = [];
for (const item of items) {
  const j = item.json;
  if (!j || j.error) continue;
  let raw = '';
  if (typeof j.data === 'string') raw = j.data;
  else if (typeof j === 'string') raw = j;
  if (!raw || raw.length < 200) continue;
  raw = raw.replace(/!\[.*?\]\(.*?\)/g, '');
  raw = raw.replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1');
  raw = raw.replace(/(https?:\/\/[^\s]+)/g, '');
  raw = raw.replace(/\n{3,}/g, '\n\n').trim();
  if (raw.length < 150) continue;
  resultadosLimpos.push({ query: queryOriginal, title: '', url: '', texto_limpo: raw.slice(0, 6000) });
}
return resultadosLimpos.map(r => ({ json: r }));

const items = $input.all();
if (items.length === 0) return [];
const idPesquisa = items[0].json.id_pesquisa;
const pronto = i => ['auditar','ok'].includes(i.json.status) && i.json.Processando === false;
const todosProntos = items.every(pronto);
return [{ json: { id_pesquisa: idPesquisa, total_subtopicos: items.length, faltam: items.filter(i => !pronto(i)).length, todos_prontos: todosProntos } }];

const i = $input.first().json;
const resp = i.resposta || '';
return [{ json: { query: i.pergunta_norm || '', title: 'cache RAG', url: 'cache://research_cache', texto_limpo: resp + (i.fontes ? '\n\nFontes: ' + i.fontes : '') } }];

const item = $input.first().json;
let queries = (item.body && item.body.queries) || item.queries || '';
if (Array.isArray(queries)) queries = queries.join(' ');
queries = String(queries);
const pergunta_norm = queries.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
return [{ json: { ...item, queries_texto: queries, pergunta_norm } }];

const items = $input.all();
const src = $('Prepara query').first().json;
const hit = items.find(i => {
  const doc = (i.json && i.json.document) ? i.json.document : i.json;
  return doc && typeof doc.pageContent === 'string' && doc.pageContent.length > 0;
});
if (!hit) return [{ json: { ...src, rag: false } }];
const doc = hit.json.document || hit.json;
const m = doc.metadata || hit.json.metadata || {};
// docs legados: veracidade texto e confiabilidade 0-10 -> escala 0-100 (mesma regra do Prepara doc cache)
function normVeracidade(v) {
  if (typeof v === 'number' && !isNaN(v)) return v <= 10 ? v * 10 : v;
  const s = String(v ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (s.includes('alta')) return 95;
  if (s.includes('media')) return 70;
  if (s.includes('baixa')) return 40;
  const n = Number(s);
  if (!isNaN(n) && s !== '') return n <= 10 ? n * 10 : n;
  return 0;
}
function normConfiabilidade(c) {
  const n = Number(c ?? 0);
  if (isNaN(n)) return 0;
  return n <= 10 ? n * 10 : Math.min(n, 100);
}
return [{ json: { rag: true, score: hit.json.score, pergunta_norm: m.pergunta_norm || src.pergunta_norm, resposta: doc.pageContent, fontes: m.fontes || '', veracidade: normVeracidade(m.veracidade), confiabilidade: normConfiabilidade(m.confiabilidade), idade_informacao: m.idade_informacao } }];

const agent = $('cria as queries para iniciar a busca1').first().json;
const out = agent.output || agent;
const step = $('Get topicos pendentes2').first().json;
const pergunta = [step.topico_principal, step.descricao_subtopico].filter(Boolean).join(' — ') || '';
const pergunta_norm = pergunta.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
let fontes = out.url_fonte || out.fontes || [];
if (!Array.isArray(fontes)) fontes = [fontes];
fontes = fontes.map(f => typeof f === 'string' ? f : (f && (f.url || f.link)) || '').filter(Boolean).join(', ');
const content = out.informacao_consolidada || out.informacao_resumida || '';
// normaliza veracidade (texto -> numero escala 0-100) e confiabilidade (0-10 -> 0-100)
function normVeracidade(v) {
  if (typeof v === 'number' && !isNaN(v)) return v <= 10 ? v * 10 : v;
  const s = String(v ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (s.includes('alta')) return 95;
  if (s.includes('media')) return 70;
  if (s.includes('baixa')) return 40;
  const n = Number(s);
  if (!isNaN(n) && s !== '') return n <= 10 ? n * 10 : n;
  return 0;
}
function normConfiabilidade(c) {
  const n = Number(c ?? 0);
  if (isNaN(n)) return 0;
  return n <= 10 ? n * 10 : Math.min(n, 100);
}
return [{ json: { content, pergunta_norm, id_pesquisa: step.id_pesquisa, fontes, veracidade: normVeracidade(out.veracidade), confiabilidade: normConfiabilidade(out.confiabilidade), idade_informacao: String(out.idade_informacao ?? '') } }];

const items = $input.all();
const out = [];
function decodeBing(u) {
  try {
    const m = u.match(/[?&]u=a1([^&]+)/);
    if (!m) return null;
    let b = m[1].replace(/-/g, '+').replace(/_/g, '/');
    while (b.length % 4) b += '=';
    return Buffer.from(b, 'base64').toString('utf8');
  } catch (e) { return null; }
}
for (const item of items) {
  const j = item.json;
  if (!j || j.error) continue;
  const raw = typeof j.data === 'string' ? j.data : '';
  if (!raw || raw.length < 300) continue;
  if (raw.includes('tráfego incomum') || raw.includes('unusual traffic')) continue;
  const re = /## \[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g;
  let m;
  while ((m = re.exec(raw)) !== null) {
    const title = m[1].trim();
    let link = m[2];
    if (link.includes('bing.com/ck/')) {
      const dec = decodeBing(link);
      if (dec && dec.startsWith('http')) link = dec; else continue;
    }
    if (link.includes('bing.com') || link.includes('microsoft.com')) continue;
    // snippet: até 300 chars após o título
    const snip = raw.slice(m.index + m[0].length, m.index + m[0].length + 400).replace(/\[[^\]]*\]\([^)]*\)/g, '').replace(/\n{2,}/g, ' ').trim().slice(0, 300);
    out.push({ json: { ok: true, title, link, snippet: snip } });
  }
}
if (out.length === 0) return [{ json: { ok: false } }];
const seen = new Set();
return out.filter(i => { if (seen.has(i.json.link)) return false; seen.add(i.json.link); return true; }).slice(0, 10);

const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json;
  if (!j || j.error) continue;
  const orgs = j.organicResults || j.organic_results || [];
  for (const o of orgs) {
    const link = o.url || o.link;
    if (!link || !link.startsWith('http')) continue;
    out.push({ json: { ok: true, title: o.title || '', link, snippet: (o.description || o.snippet || '').slice(0, 300) } });
  }
}
if (out.length === 0) return [{ json: { ok: false } }];
return out.slice(0, 10);

